Object.assign(SNIP,{});PRESET_NOTES["l42"]={"Ví dụ: Việc ngắn trước": "Theo thứ tự đến: xong lúc 6, 8, 16, 19, 20, tổng 69. Việc ngắn trước: 1, 3, 6, 12, 20, tổng 42. Thời điểm xong của khách cuối luôn là 20, nhưng các khách trước đợi ít hơn nhiều.", "Ví dụ: Đổi chỗ một cặp kề ngược": "Đổi chỗ hai việc kề nhau chỉ làm thay đổi thời điểm xong của chính hai việc đó: tổng giảm đúng 8 − 2 = 6. Lặp lại việc sửa các cặp kề ngược (như sắp xếp nổi bọt) thì tổng chỉ giảm, và dừng ở thứ tự tăng dần.", "Ví dụ: Việc có trọng số, so bằng nhân chéo": "Tỉ số t/w: 3, 0.5, 2, 0.67. Thứ tự tối ưu 1, 3, 2, 0 và tổng có trọng số 2·1 + 3·3 + 2·7 + 1·10 = 35. Nhân chéo tránh hoàn toàn sai số của số thực.", "Ví dụ: Ghép thành số lớn nhất": "“3” đứng trước “30” vì 330 > 303; “34” trước “3” vì 343 > 334. Kết quả 9534330.", "Lỗi: so chuỗi theo thứ tự từ điển khi ghép số": "So từ điển đặt “30” trước “3” (chuỗi dài hơn có cùng phần đầu thì lớn hơn), cho 9534303, nhỏ hơn 9534330. Tiêu chí đúng phải rút ra từ việc so hai cách ghép x + y và y + x."};EX_HINTS["l42"]=[["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi đúng tᵢ − tⱼ: việc ngắn nên đứng trước.", "Sắp tăng dần, cộng dồn thời điểm xong T, cộng T vào tổng.", "Tổng tới khoảng 10^5 · 10^5 · 10^9 / 2 ≈ 5·10^18: vẫn vừa long long (tối đa ≈ 9.2·10^18)."], ["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi tᵢ·wⱼ − tⱼ·wᵢ. Vậy i trước khi tᵢ·wⱼ < tⱼ·wᵢ.", "Sắp mảng chỉ số với hàm so sánh nhân chéo; đừng chia ra số thực.", "Hai khách có cùng tỉ số đứng thứ tự nào cũng được: tổng như nhau."], ["Đọc các số dưới dạng chuỗi. Hai số kề nhau x, y: x nên đứng trước khi x + y > y + x (so chuỗi cùng độ dài là so số).", "So thứ tự từ điển thông thường là sai: “30” và “3”, “121” và “12”.", "Mọi số bằng 0 thì kết quả là “000…”, phải in 0."]];
/* ===================== BÀI 42 · Chứng minh tham lam bằng lập luận hoán đổi ===================== */
/* Bài 42 · Chứng minh tham lam bằng lập luận hoán đổi
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR42=[{label:"Ví dụ: Việc ngắn trước",input:"",code:"#include <iostream>\n#include <algorithm>\nusing namespace std;\n\nint tongXong(int t[], int n) {\n    int T = 0, tong = 0;\n    for (int i = 0; i < n; i++) {\n        T += t[i];                     // khách i xong lúc T\n        tong += T;\n    }\n    return tong;\n}\n\nint main() {\n    int t[5] = {6, 2, 8, 3, 1};\n    cout << tongXong(t, 5) << \"\\n\";    // theo thứ tự đến\n    sort(t, t + 5);                    // việc ngắn trước\n    cout << tongXong(t, 5) << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"t",ptr:["i"]},{type:"vars",names:["T","tong"]}],py:{code:"def tong_xong(t):\n    T = tong = 0\n    for x in t:\n        T += x                         # khách này xong lúc T\n        tong += T\n    return tong\n\nt = [6, 2, 8, 3, 1]\nprint(tong_xong(t))                    # theo thứ tự đến\nt.sort()                               # việc ngắn trước\nprint(tong_xong(t))",viz:[{type:"bars",of:"t"},{type:"vars",names:["T","tong"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static long TongXong(int[] t)\n    {\n        long T = 0, tong = 0;\n        foreach (int x in t)\n        {\n            T += x;                        // khách này xong lúc T\n            tong += T;\n        }\n        return tong;\n    }\n\n    static void Main()\n    {\n        int[] t = { 6, 2, 8, 3, 1 };\n        Console.WriteLine(TongXong(t));        // theo thứ tự đến\n        Array.Sort(t);                         // việc ngắn trước\n        Console.WriteLine(TongXong(t));\n    }\n}",viz:[{type:"bars",of:"t"},{type:"vars",names:["T","tong"]}]}},{label:"Ví dụ: Đổi chỗ một cặp kề ngược",input:"",code:"#include <iostream>\nusing namespace std;\n\nint tongXong(int t[], int n) {\n    int T = 0, tong = 0;\n    for (int i = 0; i < n; i++) { T += t[i]; tong += T; }\n    return tong;\n}\n\nint main() {\n    int t[5] = {1, 3, 8, 2, 6};        // cặp kề (8, 2) bị ngược\n    int truoc = tongXong(t, 5);\n    swap(t[2], t[3]);                  // đổi chỗ cặp đó\n    int sau = tongXong(t, 5);\n    cout << truoc << \" - \" << sau << \" = \" << truoc - sau << \"\\n\";\n    return 0;\n}",viz:[{type:"bars",of:"t"},{type:"vars",names:["truoc","sau"]}],py:{code:"def tong_xong(t):\n    T = tong = 0\n    for x in t:\n        T += x                         # khách này xong lúc T\n        tong += T\n    return tong\n\nt = [1, 3, 8, 2, 6]                    # cặp kề (8, 2) bị ngược\ntruoc = tong_xong(t)\nt[2], t[3] = t[3], t[2]                # đổi chỗ cặp đó\nsau = tong_xong(t)\nprint(truoc, \"-\", sau, \"=\", truoc - sau)"},cs:{code:"using System;\n\nclass Program\n{\n    static long TongXong(int[] t)\n    {\n        long T = 0, tong = 0;\n        foreach (int x in t)\n        {\n            T += x;                        // khách này xong lúc T\n            tong += T;\n        }\n        return tong;\n    }\n\n    static void Main()\n    {\n        int[] t = { 1, 3, 8, 2, 6 };           // cặp kề (8, 2) bị ngược\n        long truoc = TongXong(t);\n        (t[2], t[3]) = (t[3], t[2]);           // đổi chỗ cặp đó\n        long sau = TongXong(t);\n        Console.WriteLine(truoc + \" - \" + sau + \" = \" + (truoc - sau));\n    }\n}"}},{label:"Ví dụ: Việc có trọng số, so bằng nhân chéo",input:"",code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<int> t = {3, 1, 4, 2};\n    vector<int> w = {1, 2, 2, 3};\n    vector<int> id = {0, 1, 2, 3};\n    // i đứng trước j khi t[i] / w[i] < t[j] / w[j], tức t[i] * w[j] < t[j] * w[i]\n    sort(id.begin(), id.end(), [&](int i, int j) {\n        return t[i] * w[j] < t[j] * w[i];\n    });\n    long long T = 0, tong = 0;\n    for (int k = 0; k < 4; k++) {\n        int i = id[k];\n        T += t[i];\n        tong += w[i] * T;\n        cout << i << \" \";\n    }\n    cout << \"\\n\" << tong << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"id",ptr:["k"]},{type:"vars",names:["T","tong"]}],py:{code:"from functools import cmp_to_key\n\nt = [3, 1, 4, 2]\nw = [1, 2, 2, 3]\n# i đứng trước j khi t[i] / w[i] < t[j] / w[j], tức t[i] * w[j] < t[j] * w[i]\nid = sorted(range(4), key=cmp_to_key(lambda i, j: t[i] * w[j] - t[j] * w[i]))\nT = tong = 0\nfor k in range(4):\n    i = id[k]\n    T += t[i]\n    tong += w[i] * T\nprint(*id)\nprint(tong)",viz:[{type:"cells",of:"id",ptr:["k"]},{type:"vars",names:["T","tong"]}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int[] t = { 3, 1, 4, 2 };\n        int[] w = { 1, 2, 2, 3 };\n        int[] id = { 0, 1, 2, 3 };\n        // i đứng trước j khi t[i] / w[i] < t[j] / w[j], tức t[i] * w[j] < t[j] * w[i]\n        Array.Sort(id, (i, j) => (t[i] * w[j]).CompareTo(t[j] * w[i]));\n        long T = 0, tong = 0;\n        for (int k = 0; k < 4; k++)\n        {\n            int i = id[k];\n            T += t[i];\n            tong += w[i] * T;\n            Console.Write(i + \" \");\n        }\n        Console.WriteLine();\n        Console.WriteLine(tong);\n    }\n}"}},{label:"Ví dụ: Ghép thành số lớn nhất",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<string> a = {\"3\", \"30\", \"34\", \"5\", \"9\"};\n    sort(a.begin(), a.end(), [](const string& x, const string& y) {\n        return x + y > y + x;          // x trước nếu ghép x rồi y lớn hơn\n    });\n    string kq = \"\";\n    for (string s : a) kq += s;\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"}],py:{code:"from functools import cmp_to_key\n\ndef ss(x, y):                          # âm: x đứng trước y\n    if x + y > y + x:\n        return -1\n    if x + y < y + x:\n        return 1\n    return 0\n\na = [\"3\", \"30\", \"34\", \"5\", \"9\"]\na.sort(key=cmp_to_key(ss))\nprint(\"\".join(a))",viz:[{type:"cells",of:"a"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] a = { \"3\", \"30\", \"34\", \"5\", \"9\" };\n        // x trước y khi ghép x rồi y lớn hơn; so theo mã ký tự\n        Array.Sort(a, (x, y) => string.CompareOrdinal(y + x, x + y));\n        Console.WriteLine(string.Concat(a));\n    }\n}"}},{label:"Lỗi: so chuỗi theo thứ tự từ điển khi ghép số",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    vector<string> a = {\"3\", \"30\", \"34\", \"5\", \"9\"};\n    sort(a.begin(), a.end(), [](const string& x, const string& y) {\n        return x > y;                  // SAI: so từ điển giảm dần\n    });\n    string kq = \"\";\n    for (string s : a) kq += s;\n    cout << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"a"}],py:{code:"a = [\"3\", \"30\", \"34\", \"5\", \"9\"]\na.sort(reverse=True)                   # SAI: so từ điển giảm dần\nprint(\"\".join(a))",viz:[{type:"cells",of:"a"}]},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        string[] a = { \"3\", \"30\", \"34\", \"5\", \"9\" };\n        Array.Sort(a, (x, y) => string.CompareOrdinal(y, x));   // SAI: so từ điển giảm dần\n        Console.WriteLine(string.Concat(a));\n    }\n}"}}];
