makeEx2(document.getElementById("ex-l42"),sim42,[{t:"Quầy phục vụ",d:"Một quầy phục vụ lần lượt n khách, khách i cần tᵢ phút; quầy bắt đầu lúc 0 và không nghỉ. Đầu vào: n (1 ≤ n ≤ 10^5) và n số tᵢ (1 ≤ tᵢ ≤ 10^9). Đầu ra: tổng nhỏ nhất của các thời điểm xong, khi chọn thứ tự phục vụ tốt nhất.",tests:[{in:"5\n6 2 8 3 1",out:"42"},{in:"1\n5",out:"5"},{in:"3\n2 2 2",out:"12"},{in:"3\n1000000000 1000000000 1000000000",out:"6000000000"},{in:"60\n1 38 75 12 49 86 23 60 97 34 71 8 45 82 19 56 93 30 67 4 41 78 15 52 89 26 63 100 37 74 11 48 85 22 59 96 33 70 7 44 81 18 55 92 29 66 3 40 77 14 51 88 25 62 99 36 73 10 47 84",out:"62772"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> t(n);\n    for (int i = 0; i < n; i++) cin >> t[i];\n    long long tong = 0;\n    // phục vụ khách cần ít thời gian trước\n    cout << tong << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000+1).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>60*n*Math.log2(n)+200,why:"Mỗi lần duyệt tìm khách ngắn nhất còn lại tốn O(n²). Sắp xếp một lần là O(n log n)."},py:{start:"n = int(input())\nt = list(map(int, input().split()))\ntong = 0\n# phục vụ khách cần ít thời gian trước\nprint(tong)",hints:["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi đúng tᵢ − tⱼ: việc ngắn nên đứng trước.","Sắp tăng dần, cộng dồn thời điểm xong T, cộng T vào tổng.","Số nguyên Python không tràn, không cần lo kiểu dữ liệu."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] t = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n        long tong = 0;\n        // phục vụ khách cần ít thời gian trước\n        Console.WriteLine(tong);\n    }\n}",hints:["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi đúng tᵢ − tⱼ: việc ngắn nên đứng trước.","Sắp tăng dần, cộng dồn thời điểm xong T, cộng T vào tổng.","Tổng tới khoảng 5·10^18: vẫn vừa long."]}},{t:"Khách quan trọng",d:"Như bài trước, nhưng khách i còn có mức quan trọng wᵢ. Muốn tổng wᵢ · Cᵢ nhỏ nhất, với Cᵢ là thời điểm phục vụ xong khách i. Đầu vào: n (1 ≤ n ≤ 10^5), rồi n dòng tᵢ wᵢ (1 ≤ tᵢ, wᵢ ≤ 1000). Đầu ra: tổng nhỏ nhất.",tests:[{in:"4\n3 1\n1 2\n4 2\n2 3",out:"35"},{in:"1\n5 5",out:"25"},{in:"3\n1 1\n2 2\n3 3",out:"25"},{in:"2\n10 1\n1 10",out:"21"},{in:"10\n1000 1\n1000 1\n1000 1\n1000 1\n1000 1\n1 1000\n1 1000\n1 1000\n1 1000\n1 1000",out:"30025"},{in:"50\n1 1\n38 4\n25 7\n12 10\n49 13\n36 16\n23 19\n10 22\n47 25\n34 28\n21 31\n8 34\n45 37\n32 40\n19 43\n6 46\n43 49\n30 2\n17 5\n4 8\n41 11\n28 14\n15 17\n2 20\n39 23\n26 26\n13 29\n50 32\n37 35\n24 38\n11 41\n48 44\n35 47\n22 50\n9 3\n46 6\n33 9\n20 12\n7 15\n44 18\n31 21\n18 24\n5 27\n42 30\n29 33\n16 36\n3 39\n40 42\n27 45\n14 48",out:"464857"}],start:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> t(n), w(n);\n    for (int i = 0; i < n; i++) cin >> t[i] >> w[i];\n    vector<int> id(n);\n    for (int i = 0; i < n; i++) id[i] = i;\n    // sắp id: i trước j khi t[i] * w[j] < t[j] * w[i]\n    long long tong = 0;\n    cout << tong << \"\\n\";\n    return 0;\n}",perf:{gen:n=>{const r=[];for(let i=0;i<n;i++)r.push(((i*7919)%1000+1)+" "+((i*104729)%1000+1));return n+"\n"+r.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>80*n*Math.log2(n)+200,why:"Sắp xếp bằng đổi chỗ kề nhau (nổi bọt) hay chọn lần lượt tốn O(n²)."},py:{start:"from functools import cmp_to_key\n\nn = int(input())\nt = [0] * n\nw = [0] * n\nfor i in range(n):\n    t[i], w[i] = map(int, input().split())\n# sắp chỉ số: i trước j khi t[i] * w[j] < t[j] * w[i]\ntong = 0\nprint(tong)",hints:["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi tᵢ·wⱼ − tⱼ·wᵢ. Vậy i trước khi tᵢ·wⱼ < tⱼ·wᵢ.","Dùng cmp_to_key với hàm trả về t[i] * w[j] - t[j] * w[i] (âm: i trước). Đừng chia ra số thực.","Hai khách có cùng tỉ số đứng thứ tự nào cũng được: tổng như nhau."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        long[] t = new long[n], w = new long[n];\n        int[] id = new int[n];\n        for (int i = 0; i < n; i++)\n        {\n            long[] x = Array.ConvertAll(Console.ReadLine().Split(), long.Parse);\n            t[i] = x[0];\n            w[i] = x[1];\n            id[i] = i;\n        }\n        // sắp id: i trước j khi t[i] * w[j] < t[j] * w[i]\n        long tong = 0;\n        Console.WriteLine(tong);\n    }\n}",hints:["Đổi chỗ hai khách kề nhau i, j làm tổng thay đổi tᵢ·wⱼ − tⱼ·wᵢ. Vậy i trước khi tᵢ·wⱼ < tⱼ·wᵢ.","Array.Sort(id, (i, j) => (t[i] * w[j]).CompareTo(t[j] * w[i])). Đừng chia ra số thực.","Hai khách có cùng tỉ số đứng thứ tự nào cũng được: tổng như nhau."]}},{t:"Ghép số lớn nhất",d:"Đầu vào: n (1 ≤ n ≤ 10^5) và n số nguyên 0 ≤ aᵢ ≤ 10^9. Đầu ra: số lớn nhất tạo được bằng cách viết các số liền nhau theo một thứ tự nào đó (không có chữ số 0 thừa ở đầu: nếu mọi số đều là 0 thì in 0).",tests:[{in:"5\n3 30 34 5 9",out:"9534330"},{in:"2\n10 2",out:"210"},{in:"3\n0 0 0",out:"0"},{in:"1\n1",out:"1"},{in:"2\n121 12",out:"12121"},{in:"2\n824 8247",out:"8248247"},{in:"40\n0 37 74 111 148 185 22 59 96 133 170 7 44 81 118 155 192 29 66 103 140 177 14 51 88 125 162 199 36 73 110 147 184 21 58 95 132 169 6 43",out:"969588817747366659585144433736292221199192185184177170169162155148147141401331321251181111101030"}],start:"#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    // sắp với hàm so sánh: x trước y khi x + y > y + x\n    string kq = \"\";\n    cout << kq << \"\\n\";\n    return 0;\n}",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%1000).join(" "),ns:[250,500,1000,2000],need:"nlogn",limit:n=>200*n*Math.log2(n)+200,why:"Chọn lần lượt số “tốt nhất” còn lại tốn O(n²) phép so sánh."},py:{start:"from functools import cmp_to_key\n\nn = int(input())\na = input().split()\n# sắp với hàm so sánh: x trước y khi x + y > y + x\nkq = \"\"\nprint(kq)",hints:["Giữ các số dưới dạng chuỗi. Hai số kề nhau x, y: x nên đứng trước khi x + y > y + x.","Viết hàm so sánh trả về -1 / 1 / 0 rồi dùng a.sort(key=cmp_to_key(ss)). So từ điển thông thường là sai: “30” và “3”.","Mọi số bằng 0 thì kết quả là “000…”, phải in 0."]},cs:{start:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = int.Parse(Console.ReadLine());\n        string[] a = Console.ReadLine().Split();\n        // sắp với hàm so sánh: x trước y khi x + y > y + x\n        string kq = \"\";\n        Console.WriteLine(kq);\n    }\n}",hints:["Giữ các số dưới dạng chuỗi. Hai số kề nhau x, y: x nên đứng trước khi x + y > y + x.","Dùng string.CompareOrdinal(y + x, x + y) làm hàm so sánh (so theo mã ký tự, không phụ thuộc ngôn ngữ máy).","Mọi số bằng 0 thì kết quả là “000…”, phải in 0."]}}]);

